"""Authored clinical/patient facts for the final six GU suites; sources retained in validation."""
def facts(agent):
 carbo=agent('00568','carboplatin');etop=agent('00561','etoposide');pac=agent('00621','paclitaxel');cis=agent('00281','cisplatin');pembro=agent('00568','pembrolizumab');ev=agent('00846','enfortumab_vedotin')
 def medicine(id,name,type,mechanism,explanation,risks,watch):return dict(id=id,name=name,alias=name,type=type,mechanism=mechanism,explanation=explanation,visual=['Treatment target','Cancer-cell effect','Healthy-tissue effects'],risks=risks,watch=watch,symptoms=({'ifosfamide':['Fever / chills','Urinary symptoms','Weakness','Nausea'],'bcg_intravesical':['Urinary symptoms','Fever / chills','Fatigue'],'gemcitabine_intravesical':['Urinary symptoms','Fever / chills','Skin'],'docetaxel_intravesical':['Urinary symptoms','Fever / chills','Skin'],'erdafitinib':['Eye symptoms','Skin / nail changes','Mouth soreness / ulcers','Diarrhoea']}.get(id,['Urinary symptoms','Fever / chills'])),source_ids=['nccp'])
 ifos=medicine('ifosfamide','Ifosfamide','Chemotherapy','Damages DNA needed for cell division','Ifosfamide damages cancer-cell DNA. Its breakdown products can also affect the bladder, kidneys and brain. Mesna protects the bladder but does not prevent all kidney or brain effects.',['Low blood counts, serious infection, anaemia and bleeding','Bladder inflammation and bleeding; kidney and electrolyte problems','Confusion, drowsiness, hallucinations or seizures (encephalopathy)','Nausea, mouth soreness, hair loss, fatigue and fertility harm','Rare serious heart or lung effects and later blood cancers'],'Report confusion, sleepiness, blood in urine or reduced urine immediately.')
 bcg=medicine('bcg_intravesical','BCG','Intravesical live bacterial immunotherapy','Activates immune cells in the bladder lining','BCG contains weakened live bacteria. Placing it inside the bladder stimulates a local immune response against abnormal cells. It is not a checkpoint-inhibitor medicine.',['Burning, urgency, frequent urination, bladder discomfort and blood in urine','Flu-like symptoms, tiredness and fever','Uncommon or rare serious infection spreading beyond the bladder, including sepsis; this can be fatal','Inflammation of the prostate, testis/epididymis, joints or eyes; possible fertility effects','Bladder shrinkage/contracture and lasting urinary problems','Delayed BCG infection may appear months or years after treatment'],'Call urgently for fever, shaking chills, marked illness, breathlessness or inability to pass urine. Always tell other clinicians about prior BCG.')
 gem=medicine('gemcitabine_intravesical','Gemcitabine in the bladder','Intravesical chemotherapy','Interferes with DNA copying in bladder-lining cells','Gemcitabine is placed directly in the bladder, held there and drained before docetaxel. Local treatment limits exposure elsewhere but does not guarantee that systemic effects cannot occur.',['Bladder irritation, urgency, frequent or painful urination, blood or tissue in urine','Urinary infection and catheter discomfort or injury','Nausea and tiredness; allergy or systemic effects can occur','Rare severe bladder injury or lasting reduction in bladder capacity'],'Report fever, persistent bleeding, severe pain or inability to pass urine.')
 doc=medicine('docetaxel_intravesical','Docetaxel in the bladder','Intravesical chemotherapy','Disrupts the cell machinery needed for division','Docetaxel is instilled after gemcitabine has been drained. It acts on dividing cells in the bladder lining. Its dose and preparation are different from intravenous docetaxel.',['Bladder irritation, spasm, urgency and painful urination','Urinary infection, blood in urine and catheter discomfort','Allergy or systemic effects can occur; tell the team about new rash or breathlessness','Rare severe or lasting urinary problems'],'Do not substitute intravenous docetaxel instructions or steroid premedication for this bladder plan.')
 erda=medicine('erdafitinib','Erdafitinib','Targeted FGFR inhibitor','Blocks abnormal FGFR signalling','Some urothelial cancers use an altered fibroblast growth factor receptor, FGFR3, to drive growth. Erdafitinib blocks this signal. FGFR also helps regulate phosphate handling, explaining why blood phosphate may rise.',['High phosphate and other electrolyte changes; prolonged elevation may harm tissues','Retinal fluid/central serous retinopathy, blurred vision and other eye problems','Sore mouth, dry mouth, altered taste and reduced appetite','Nail changes/infection, dry skin, rash and painful palms or soles','Diarrhoea, fatigue, hair changes and liver/kidney-test changes'],'Report any new blurred vision, visual distortion or eye pain promptly; do not wait for the next routine eye appointment.')
 def amap(rows):
  pos={'brain':(50,8),'eyes':(50,11),'mouth':(50,14),'lungs':(61.5,24.7),'heart':(48,25),'liver':(43,33),'kidneys':(39.5,38.6),'bowel':(50,44.5),'bladder':(50,52),'blood':(39,39),'skin':(65,70),'nerves':(35,77),'joints':(64,53)}
  return [[key,label,drug,text,*pos[key]] for key,label,drug,text in rows]
 txmap=amap([('brain','Hearing / nerves','Carboplatin / etoposide','Report ringing ears, hearing changes, confusion or new weakness.'),('mouth','Mouth','High-dose chemotherapy','Mouth ulcers may make eating and drinking difficult; ask for pain and nutrition support.'),('lungs','Breathing','Treatment / infection','New cough or breathlessness needs urgent assessment.'),('liver','Liver','Chemotherapy','Daily blood tests check liver effects; report jaundice.'),('kidneys','Kidneys / fluid balance','Carboplatin / etoposide','Report reduced urine or rapid weight gain; follow the prescribed fluid plan.'),('bowel','Stomach / bowel','Chemotherapy','Report vomiting, diarrhoea, severe pain or inability to drink.'),('blood','Blood / infection','High-dose chemotherapy','Profound low counts are expected. Fever or sudden illness needs immediate treatment.'),('skin','Skin / hair / fertility','Chemotherapy','Hair loss and skin effects may occur. Discuss fertility preservation and lasting risks before treatment.')])
 tipmap=amap([('brain','Brain / alertness','Ifosfamide','Report confusion, unusual sleepiness, hallucinations or seizures immediately.'),('mouth','Mouth','Chemotherapy','Tell the team about ulcers or difficulty drinking.'),('heart','Heart / reactions','Paclitaxel','Tell the nurse immediately about chest symptoms, faintness, rash or breathing difficulty.'),('kidneys','Kidneys / hearing','Cisplatin / ifosfamide','Report reduced urine, ringing ears or hearing changes; tests check electrolytes.'),('bladder','Bladder','Ifosfamide','Mesna helps protect the bladder. Blood in urine or pain still needs urgent review.'),('blood','Blood / infection','Chemotherapy','Fever, chills, sudden illness or unusual bleeding needs immediate help.'),('skin','Skin / hair','Paclitaxel / ifosfamide','Report drip-site pain or swelling, severe rash or blistering.'),('nerves','Hands / feet','Paclitaxel / cisplatin','Report tingling, numbness or trouble with fine tasks and walking early.')])
 bcgmap=amap([('bladder','Bladder / urine','BCG / catheter','Burning and frequency can occur. Severe pain, bleeding or inability to pass urine needs urgent advice.'),('blood','Whole-body infection','BCG','Fever, chills or marked illness can signal serious BCG infection. Call immediately.'),('lungs','Lungs','BCG infection / inflammation','New cough or breathlessness needs urgent assessment.'),('liver','Liver','BCG infection / inflammation','Report yellow eyes, dark urine or persistent unexplained illness.'),('eyes','Eyes','Inflammatory reaction','New painful, red or blurred eyes need prompt review.'),('joints','Joints','Inflammatory reaction','Report new painful or swollen joints.'),('skin','Skin / allergy','BCG','Report a widespread rash; severe allergic symptoms require emergency help.'),('nerves','Genital / fertility effects','BCG','Report testicular pain or swelling. Discuss sperm preservation and sexual precautions.')])
 bladdermap=amap([('bladder','Bladder','Gemcitabine / docetaxel','Burning, urgency and bladder spasm can occur; report severe or persistent symptoms.'),('kidneys','Passing urine','Treatment / catheter','Report blood in urine, reduced urine or inability to empty the bladder.'),('blood','Infection','Treatment / catheter','Fever, chills or sudden illness needs urgent advice, even though treatment is local.'),('bowel','Nausea','Treatment','Tell the team if nausea occurred after a previous instillation.'),('skin','Skin / allergy','Either medicine','Report rash; breathing difficulty, collapse or swelling of lips/tongue needs emergency help.'),('nerves','Discomfort / fatigue','Treatment','Tell the team about pain or fatigue that interferes with daily life.'),('lungs','Breathing','Possible systemic reaction','New breathlessness needs urgent review. Local administration does not exclude all systemic effects.'),('mouth','Other unexpected effects','Either medicine','Report unexpected mouth ulcers or other new symptoms so the team can check the cause.')])
 erdamap=amap([('eyes','Eyes / retina','Erdafitinib','New blurred or distorted vision or eye pain needs prompt eye assessment.'),('mouth','Mouth','Erdafitinib','Report soreness, dry mouth or difficulty eating and drinking.'),('skin','Skin / nails','Erdafitinib','Report painful nails, infected nail folds, rash or sore palms/soles.'),('bowel','Bowel','Erdafitinib','Report frequent diarrhoea, pain or dehydration.'),('kidneys','Phosphate / kidneys','Erdafitinib','Blood tests detect high phosphate, often before symptoms. Follow the agreed diet and binder plan.'),('liver','Liver','Erdafitinib','Blood tests check the liver. Report yellow eyes or dark urine.'),('blood','Fatigue / blood tests','Erdafitinib','Tell the team about worsening tiredness, dizziness or sudden illness.'),('heart','Heart / medicines','Erdafitinib / interactions','Report palpitations or faintness and show the team all medicines and supplements.')])
 evmap=amap([('skin','Skin','Enfortumab / pembrolizumab','Report rash early. Blisters, peeling, mouth sores or fever with rash require urgent assessment.'),('nerves','Hands / feet','Enfortumab','Report tingling, numbness, weakness or difficulty walking early.'),('lungs','Lungs','Either medicine','New cough or breathlessness may be lung inflammation; seek urgent advice.'),('bowel','Bowel','Pembrolizumab / enfortumab','Report new diarrhoea, blood in stool or abdominal pain; do not assume it is a routine side effect.'),('liver','Liver','Either medicine','Blood tests check inflammation. Report jaundice or dark urine.'),('kidneys','Kidneys / hormones','Pembrolizumab','Report reduced urine, dizziness, severe weakness or persistent headache.'),('blood','Blood sugar','Enfortumab / pembrolizumab','Thirst, frequent urine, vomiting or drowsiness may indicate dangerously high glucose.'),('eyes','Eyes / other organs','Either medicine','Report visual changes. Immune inflammation can affect almost any organ, including heart, nerves and muscles.')])
 return {
 '00453':dict(title='High-dose carboplatin + etoposide with stem-cell rescue',context='Relapsed germ-cell cancer · specialist transplant pathway',purpose='Aim for lasting cancer control or cure in selected relapsed germ-cell cancer, using high-dose chemotherapy with your own stored stem cells.',days=14,kind='reference-course',label='Chemotherapy days −5 to −3 · stem cells day 0',agents=[carbo,etop],anatomy=txmap,
 schedule='Carboplatin AUC7 is followed by etoposide 750 mg/m² on days −5, −4 and −3. Your stored stem cells are infused on day 0. Growth-factor injections start on day +1 and continue until the team confirms neutrophil recovery. These day numbers are relative to the stem-cell infusion.',
 administration='Chemotherapy and stem-cell rescue take place in a specialist transplant service. Carboplatin runs over 30 minutes and etoposide over two hours on each treatment day. Preparation, fluid management and monitoring add time. Staff give stem-cell infusion premedication under the local plan.',
 baseline='Blood count, kidney/liver profile, LDH, urate, lung-function tests, heart ultrasound, virology screen and kidney-filtration assessment. Measured GFR is preferred when feasible; hearing tests if indicated. Confirm sufficient collected stem cells and transplant fitness.',
 monitoring='Blood count and kidney/liver profile daily during therapy, with fluid balance and daily weights. The transplant team confirms infection monitoring, blood-product support and when counts have recovered.',
 support='Prescribed anti-sickness treatment is needed across the high-dose days. The local transplant plan includes antiviral and antifungal prevention, mouth care, a proton-pump inhibitor and Pneumocystis pneumonia prevention. Co-trimoxazole starts only after engraftment; the team specifies the stop date. Irradiated cellular blood components are required from one week before conditioning until 12 months after stem-cell infusion.',
 prep='Confirm admission, stored stem-cell availability, fertility discussion and the complete transplant-support prescription before conditioning.',access='The transplant team arranges suitable intravenous access and line care. Record that you require irradiated cellular blood components and tell every treating service.',
 wider='Your stem cells help restore blood-cell production after intensive chemotherapy; they are not donor cells. A second high-dose course may be considered after recovery, at least 28 days later, depending on response and toxicity. Later oral etoposide is only considered in selected responders after two courses and is not automatic.',
 scope='A specialist conditioning and rescue pathway. The diagram is a relative reference, not an outpatient 28-day cycle or a discharge prediction.',
 trial='High-dose chemotherapy and stem-cell rescue · Einhorn 2007',trial_url='https://pubmed.ncbi.nlm.nih.gov/17652649/',evidence='In a retrospective series of 184 previously treated patients, 116 remained in complete remission without relapse during a median follow-up of 48 months. Three treatment-related deaths and three later cases of acute leukaemia were reported.',caveat='This was not a randomised comparison. It used carboplatin 700 mg/m², whereas NCCP00453 uses AUC7. The study supports the treatment approach but its dose and outcomes must not be presented as identical to this protocol.',doses=[('conditioning','High-dose chemotherapy: days −5 to −3',1,3,'Relative to the stem-cell infusion, not cycle day1.'),('rescue','Stem-cell infusion: day0',6,6,'Your own stored stem cells.'),('recovery','Growth factor and recovery: from day+1',7,14,'Duration depends on blood-count recovery, not the end of this graphic.')],phases=[('conditioning','High-dose chemotherapy and transplant support',['carboplatin','etoposide'],'high')]),
 '00602':dict(title='TIP: paclitaxel, ifosfamide and cisplatin',context='Relapsed testicular germ-cell cancer',purpose='Treat relapsed or resistant testicular germ-cell cancer, with the possibility of lasting remission in selected patients.',days=21,kind='cyclical',label='Chemotherapy days 1–5 · every 21 days · four cycles',agents=[pac,ifos,cis],anatomy=tipmap,
 schedule='Paclitaxel is given on day 1. Cisplatin and ifosfamide are given on days 1–5, with bladder-protecting mesna each day. Growth-factor injections start on day 6 until neutrophil recovery under local policy. Four 21-day cycles are planned, subject to consultant review.',
 administration='Paclitaxel runs over three hours on day1, cisplatin over one hour and ifosfamide over two hours on days1–5. Mesna is given immediately before ifosfamide and again four and eight hours after the ifosfamide infusion finishes. The unit coordinates the complete schedule; do not calculate home timings yourself.',
 baseline='Blood count, kidney and liver profile; review hearing and neuropathy. Hearing tests and measured/estimated creatinine clearance are arranged when indicated. Discuss fertility preservation before salvage chemotherapy.',monitoring='Blood count, kidney and liver profile before each treatment. Staff check neurological function daily during ifosfamide and urine for blood before and daily during it. Review hearing, nerves, hydration, electrolytes and fluid balance.',
 support='Cisplatin needs a high-risk anti-sickness plan and prescribed hydration/electrolytes. Ifosfamide needs mesna and adequate fluids. Paclitaxel needs prescribed allergy premedication; reconcile steroid doses with antiemetics. Aprepitant may increase ifosfamide brain toxicity, so pharmacy must review the combination. Growth factor is included from day6. Retain prescribed mouth care, pain relief and stomach protection.',prep='Confirm the five-day attendance/admission plan, mesna timings, hydration, allergy prevention and growth-factor prescription.',access='Suitable intravenous access is needed for repeated infusions. Report drip-site pain or swelling immediately. Admission and line choice are agreed locally.',wider='The germ-cell specialist team chooses salvage chemotherapy using previous response, relapse timing, tumour markers and disease extent. Surgery for remaining masses or a high-dose stem-cell pathway may be considered separately; neither is automatically part of this calendar.',scope='This is NCCP00602: paclitaxel175 mg/m² day1, ifosfamide1200 mg/m² and cisplatin20 mg/m² days1–5. Other published TIP schedules differ.',trial='MRC phase II TIP study · Mead2005',trial_url='https://pubmed.ncbi.nlm.nih.gov/15999102/',evidence='Among 43 patients eligible for response assessment, the favourable response rate was60% (95% confidence interval44–75%). This combined complete responses with partial responses in which tumour markers became negative.',caveat='This small, non-randomised study used ifosfamide1000 mg/m²/day, compared with1200 mg/m²/day in NCCP00602. A favourable response is not the same as cure, and these results cannot predict an individual outcome.',doses=[('pac','Paclitaxel',1,1,'With prescribed allergy premedication.'),('ic','Cisplatin + ifosfamide + mesna',1,5,'Mesna and fluids are part of every treatment day.'),('gcsf','Growth factor from day6',6,6,'Continue until recovery according to the prescribed plan.')],phases=[('five_days','Five-day chemotherapy and protection plan',['paclitaxel','ifosfamide','cisplatin'],'high')]),
 '00807':dict(title='BCG bladder treatment',context='Non-muscle-invasive bladder cancer',purpose='Reduce the risk of bladder cancer returning or worsening, and treat suitable carcinoma in situ, using local immune treatment.',days=42,kind='reference-course',label='Six weekly induction treatments · then risk-specific maintenance',agents=[bcg],anatomy=bcgmap,service_kind='intravesical',
 schedule='BCG is placed in the bladder once weekly for six weeks. Maintenance uses three weekly instillations at months3,6 and12 for intermediate-risk disease; high/very-high-risk plans may add months18,24,30 and36. Your urologist confirms the course according to risk, response, tolerance and supply.',administration='A urinary catheter is used to place one prescribed vial of BCG into the bladder, usually in up to50 mL saline. NCCP gives a dwell time of one to two hours; BCG-medac instructions specify two hours. Staff confirm your product and how and when to empty your bladder.',baseline='Cystoscopy with biopsy or resection confirms diagnosis. The urologist reviews risk group, healing after procedures, infection, bleeding, immune suppression, medicines and the chosen BCG product.',monitoring='Check symptoms and suitability before each instillation. Cystoscopy with possible biopsy and urine cytology are planned eight weeks after the last BCG dose and regularly afterwards under the urologist’s plan.',support='Routine anti-sickness or steroid premedication is not usually needed. The source asks for no fluids for four hours before and until two hours after instillation; confirm this is safe with your team, especially with fluid-sensitive conditions. Obtain written instructions for restarting fluids, passing urine, toilet hygiene, spill management and sexual precautions for your exact product.',prep='Tell the unit about fever, urinary infection, visible blood, recent bladder surgery/biopsy, antibiotics or immune-suppressing medicines before attending.',access='Treatment uses a temporary urinary catheter, not an intravenous chemotherapy pump. Catheter trauma or bleeding may mean postponement. Do not stop prescribed medicines or diuretics without the team’s instructions.',wider='Cystoscopy surveillance remains essential after BCG. Persistent high-grade disease or progression needs a fresh specialist discussion, which may include bladder removal or other treatment. Maintenance is not proof that the cancer has been cured.',scope='Live BCG placed inside the bladder. It is not intravenous chemotherapy or PD1/PDL1 checkpoint immunotherapy.',trial='NCCP00807 and BCG-medac product information',trial_url='https://assets.hpra.ie/products/Human/19330/Licence_PA0623-004-001_02042025124042.pdf',evidence='BCG stimulates immune activity in the bladder. Maintenance can reduce recurrence and may reduce progression, but its benefit must be weighed against urinary symptoms, serious infection risk and the individual cancer risk.',caveat='The NCCP schedule allows different BCG products. Product-specific exclusions and precautions must be checked; the BCG-medac information is not permission to substitute brands without review.',doses=[('bcg'+str(w),'BCG week'+str(w),1+7*(w-1),1+7*(w-1),'Weekly induction appointment after safety checks.')for w in range(1,7)],phases=[('instillation','BCG instillation and home precautions',['bcg_intravesical'],'minimal')]),
 '00885':dict(title='Erdafitinib: targeted tablets',context='FGFR3-selected advanced urothelial cancer',purpose='Help control advanced urothelial cancer with a susceptible FGFR3 alteration after previous PD1/PDL1 treatment.',days=28,kind='continuous',label='Daily tablets · early phosphate review on days14–21',agents=[erda],anatomy=erdamap,service_kind='targeted',
 schedule='The usual starting dose is8 mg once daily. The team may increase it to9 mg after reviewing phosphate and toxicity on days14–21. Never change the dose yourself. Treatment is continuous until progression or unacceptable toxicity; the28-day view is only a reference.',administration='Swallow tablets whole, with or without food, at about the same time each day. Avoid grapefruit and Seville oranges. If a dose is missed, take it as soon as possible and resume the usual schedule next day; never take extra tablets. If you vomit after a dose, take the next dose the following day.',baseline='Confirm the FGFR3 result and previous treatment. Blood count, kidney/liver profile, phosphate, urea/electrolytes, heart history/examination, ECG and eye examination are required at baseline.',monitoring='Phosphate is checked on days14–21 and monthly afterwards, more often if elevated. Eye examinations are monthly for the first four months and every three months thereafter; new symptoms need prompt review. Repeat blood count, kidney/liver tests, electrolytes and ECG under the prescribed plan.',support='High phosphate may need a dietitian-guided phosphate restriction and prescribed phosphate binder. Do not add vitaminD supplements without oncology review. Ask about mouth care, skin/nail care, diarrhoea treatment and dry-eye support. Bring all medicines and supplements for interaction checking.',prep='Confirm the tablet strength, daily dose, early phosphate appointment and baseline eye examination before starting.',access='This is oral treatment; it does not require routine infusion access or a pump. Store and handle tablets as advised and keep a dose record.',wider='FGFR testing selects people whose tumour may respond to this mechanism. Treatment aims to control cancer; scans and symptoms assess benefit separately from phosphate and other safety tests. Other systemic treatment or symptom-directed radiotherapy depends on your individual situation.',scope='The molecular result must be a susceptible FGFR3 alteration. A general FGFR result or a phosphate rise alone does not prove tumour benefit.',trial='THOR randomised phase III study',trial_url='https://pubmed.ncbi.nlm.nih.gov/37870920/',evidence='After previous PD1/PDL1 therapy, median overall survival was12.1 months with erdafitinib versus7.8 months with chemotherapy (hazard ratio0.64;95% confidence interval0.47–0.88). Median progression-free survival was5.6 versus2.7 months.',caveat='These are trial group estimates, not a personal prognosis. Trial molecular eligibility included FGFR3/2 alterations; the current Irish indication requires susceptible FGFR3 alterations.',doses=[('tablets','Erdafitinib each day',1,28,'Only the prescribed dose; no self-escalation.'),('phosphate','Early phosphate and toxicity review',14,21,'The team decides whether escalation is appropriate.')],phases=[('daily','Daily tablets and phosphate/eye monitoring',['erdafitinib'],'minimal')]),
 '00894':dict(title='Gemcitabine + docetaxel bladder treatment',context='High-risk non-muscle-invasive bladder cancer',purpose='Treat selected high-risk bladder cancer when BCG has not worked, cannot be tolerated or is unsuitable.',days=42,kind='reference-course',label='Six weekly instillations · selected monthly maintenance',agents=[gem,doc],anatomy=bladdermap,service_kind='intravesical',
 schedule='Both medicines are given at each weekly induction visit for six weeks. Selected patients then receive treatment monthly for18 months, beginning six weeks after the final induction dose. Maintenance depends on response and tolerability; it is not automatic.',administration='Gemcitabine1000 mg in50 mL is instilled through a urinary catheter and held for60 minutes, then drained. Docetaxel40 mg in50 mL follows and is held for60 minutes. The team may use90-minute dwell times. These are fixed bladder doses, not intravenous doses based on body size.',baseline='Cystoscopy with biopsy or resection confirms diagnosis. Confirm healing after surgery, no recent bleeding or catheter trauma, and assess urine for infection. Tell the urologist about pregnancy, breastfeeding, allergies and bladder capacity problems.',monitoring='Before treatment, urine dipstick and symptom assessment help check for infection; symptoms require urology review. Response assessment determines maintenance. If disease-free, cystoscopy with cytology is usually every three months for two years.',support='The source includes prescribed sodium bicarbonate1200 mg the night before and1200 mg one hour before treatment to reduce bladder irritation. Anti-sickness medicine may be considered if nausea followed a previous instillation. Pain or spasm medicines are individual prescriptions; ask before taking ibuprofen or other medicines.',prep='Confirm the bicarbonate prescription and the fluid/diuretic plan. The source advises avoiding fluids for four hours before and until two hours after instillation, and avoiding alcohol/coffee around treatment. The team must adapt instructions for your medical conditions; do not change a prescribed diuretic yourself.',access='A temporary urinary catheter is used; no routine intravenous line or take-home pump is needed. Obtain written instructions for passing urine, toilet hygiene, skin exposure and sexual/contraceptive precautions.',wider='This is a bladder-preserving option for selected patients. Cystoscopy remains necessary; high-grade recurrence or progression requires discussion of other options, including bladder removal where suitable.',scope='Intravesical gemcitabine/docetaxel uses an unlicensed route and dose schedule in Ireland. The clinician must discuss this and follow hospital approval/consent policy.',trial='NCCP00894 and sequential intravesical treatment evidence',trial_url='https://pubmed.ncbi.nlm.nih.gov/31821066/',evidence='Published multi-centre observational evidence supports sequential gemcitabine/docetaxel as a bladder-preserving salvage option after BCG. The NCCP regimen defines the Irish doses, sequence and selected maintenance plan.',caveat='Observational results do not establish equivalence to cystectomy or other options. Published schedules differ; follow the NCCP regimen and individual urology plan, with explicit discussion of unlicensed use.',doses=[('inst'+str(w),'Gemcitabine then docetaxel · week'+str(w),1+7*(w-1),1+7*(w-1),'Gemcitabine is drained before docetaxel is instilled.')for w in range(1,7)],phases=[('instillation','Bladder instillation and prescribed preparation',['gemcitabine_intravesical','docetaxel_intravesical'],'minimal')]),
 '00945':dict(title='Enfortumab vedotin + pembrolizumab',context='First-line unresectable or metastatic urothelial cancer',purpose='Help control advanced urothelial cancer using a targeted chemotherapy-carrying antibody and immune treatment.',days=42,kind='reference-course',label='Confirm21-day or42-day pembrolizumab plan · EV days1/8 in each21-day block',agents=[ev,pembro],anatomy=evmap,service_kind='chemoimmunotherapy',
 schedule='Option1: enfortumab on days1 and8 plus pembrolizumab200 mg on day1, repeating every21 days. Option2: enfortumab on days1,8,22 and29 plus pembrolizumab400 mg on day1, repeating every42 days. Your team selects one option. The six-week reference shows two enfortumab blocks; pembrolizumab day22 applies only to option1.',administration='Enfortumab is given first over30 minutes; pembrolizumab follows over30 minutes when both are due. Enfortumab starts at1.25 mg/kg with a125 mg cap. Staff confirm your current dose and chosen pembrolizumab interval; pembrolizumab is not dose-reduced for toxicity.',baseline='Blood count, kidney/liver profile, glucose, HbA1c, lipase and thyroid tests; assess skin and nerves. Eye examination and ECG are arranged when indicated. Review diabetes, immune conditions, medicines and previous treatment.',monitoring='NCCP specifies blood count, kidney/liver profile and glucose on days1 and8 of cycle1 and day1 of later cycles. Thyroid tests every3–6weeks; skin checks throughout. HbA1c, lipase, cortisol, nerve and eye reviews depend on symptoms and the plan. For the42-day option, the team must explicitly confirm tests for each enfortumab block.',support='Follow the prescribed low-risk anti-sickness plan for enfortumab. Ask about moisturiser, skin care and artificial tears. After a prior enfortumab infusion reaction, the team may prescribe antihistamine, antipyretic and intravenous steroid before later infusions. Immune effects need assessment; do not treat new diarrhoea or breathlessness as routine without contacting the team.',prep='Confirm the chosen21-day or42-day schedule, glucose plan, skin/nerve baseline and both medicine alert cards.',access='Suitable intravenous access is needed. There is no routine take-home pump. Report pain, redness or swelling at the infusion site immediately.',wider='Treatment continues while effective and tolerable. At24months, stopping pembrolizumab may be considered for sustained response without progression, but this is not mandatory. Radiotherapy may help selected symptoms; the regimen does not automatically prescribe surgery or a perioperative pathway.',scope='This is the NCCP00945 advanced-disease combination. It is distinct from28-day enfortumab monotherapy and from perioperative bladder treatment.',trial='EV-302 randomised phase III study',trial_url='https://pubmed.ncbi.nlm.nih.gov/38446675/',evidence='In886 previously untreated patients, median overall survival was31.5 months with the combination versus16.1 months with platinum/gemcitabine (hazard ratio0.47;95% confidence interval0.38–0.58). Median progression-free survival was12.5 versus6.3 months.',caveat='These are results from the primary analysis, not a personal prognosis or a comparison with every possible treatment sequence. The current NCCP indication specifies eligibility for platinum-containing chemotherapy.',doses=[('ev','Enfortumab',1,1,'Both options.'),('ev8','Enfortumab',8,8,'Both options.'),('ev22','Enfortumab',22,22,'Second21-day block.'),('ev29','Enfortumab',29,29,'Second21-day block.'),('pembro1','Pembrolizumab',1,1,'200 mg for option1 or400 mg for option2.'),('pembro22','Pembrolizumab: option1 ONLY',22,22,'Only200 mg q21 plan; no pembrolizumab here for400 mg q42 plan.')],phases=[('both','Visits when both medicines are due',['enfortumab_vedotin','pembrolizumab'],'low'),('ev_only','Enfortumab-only visits',['enfortumab_vedotin'],'low')])
 }
